WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY amount NULLS LAST, id) AS rank_in_group FROM orders QUALIFY rank_in_group = 1) SELECT id, customer_id, store_id, order_date, channel, discount, shipping_fee, rank_in_group, CASE WHEN channel RLIKE '^(mobile|web)$' THEN 'PRIORITY' WHEN channel RLIKE '^(store|partner)$' THEN 'GROUP_B' ELSE 'OTHER_ZONE' END AS channel_zone FROM deduped ORDER BY shipping_fee;
